     1	/**
     2	 * Recipe for the PDP meta block — the model line and the style code, which the design places
     3	 * at the bottom of the info column below the accordions.
     4	 *
     5	 * Multipart with a single `root` part rather than a bare `baseStyle`: `ui-kits/recipeParts.test.ts`
     6	 * reconciles a declared `parts` array against what the sibling component actually reads off
     7	 * `useMultiStyleConfig`, and a recipe with no `parts` key is skipped by that walk entirely.
     8	 * Declaring the one part buys the reconciliation for the two-node shape this block will grow
     9	 * into when the designer settles the label/value question raised in `zimmProductStyleCode.css.ts`.
    10	 */
    11	
    12	/**
    13	 * DS: 28px between the drawers and the model line, and again between the model line and the
    14	 * style code — identical on both breakpoints (pdp/product-content, desktop and mobile Default).
    15	 * Figma: pdp/product-content, Desktop Default 40000307:14062 / Mobile Default 40000343:9727.
    16	 *
    17	 * A rem literal because no rem-valued 28px token exists to reference. `spacing.ts` brackets it
    18	 * at `xl` (1.5rem/24px) and `2xl` (2rem/32px) with nothing between, and `--zimm-scale-700` — the
    19	 * one alias that does hold 28px — is itself a raw px string in `zimmTokens.ts`, not a reference
    20	 * to a named step the way its neighbours `--zimm-scale-600`/`-800` reference `spacing.xl`/`2xl`.
    21	 * Substituting it would silently convert spacing that scales with the user's root font size into
    22	 * fixed px, which is what overrideStyling.md's Units rule rules out for spacing (WCAG 1.4.4).
    23	 *
    24	 * `theme/components/listMenu.ts` (lines 17, 33, 65, 84) does use `var(--zimm-scale-700)` for its
    25	 * own 28px, so the precedent in this repo is genuinely split — noted here so the next reader does
    26	 * not read that file as evidence this one is wrong and "align" it into a px value. The Units rule
    27	 * is what decides, and it points at rem for spacing. Pending a named 28px step from the UI
    28	 * designer both should converge on; listMenu.ts is designer-owned Tier 2 and not this file's to
    29	 * change. Do not swap for `xl` or `2xl`, both visibly wrong.
    30	 */
    31	const SPACE_META_ROW = '1.75rem'; // 28px at the default 16px root
    32	
    33	export const ZimmProductMeta = {
    34	  parts: ['root'],
    35	  baseStyle: {
    36	    // One const drives both hops because the design measures both at 28px. Written as a `gap`
    37	    // plus a `paddingTop` on the same container — the pattern `footer.css.ts` (lines 41-42)
    38	    // already uses with its own SPACE_SECTION — so the two cannot drift apart.
    39	    root: {
    40	      display: 'flex',
    41	      flexDirection: 'column',
    42	      alignItems: 'flex-start',
    43	      gap: SPACE_META_ROW, // model line -> style code
    44	      paddingTop: SPACE_META_ROW, // drawers -> model line
    45	    },
    46	  },
    47	};
