     1	/**
     2	 * Scoped to this molecule's own contract per testing.md: which of its two rows render, in which
     3	 * order, and whether the block itself renders at all.
     4	 *
     5	 * `app/utils/richText` is mocked, the same way the two child atoms' own suites mock it — its
     6	 * behaviour is exhaustively proven in app/utils/richText.test.tsx. The mocks are
     7	 * `mockImplementation`, not `mockReturnValue`: a fixed return ignores its argument, so a
     8	 * molecule that dropped `modelInfo` on the way to the atom, or handed the guard `styleCode`
     9	 * instead of `modelInfo`, would still produce exactly the render the test expected. Keying each
    10	 * mock off its input is what makes those two prop-to-state mistakes fail here.
    11	 *
    12	 * The atoms are left real because composition is part of the contract: `index.tsx` fixes the
    13	 * model line above the style code, asserted below by position rather than by presence, and each
    14	 * atom must still collapse independently inside this wrapper.
    15	 *
    16	 * The all-absent case is the reason this file exists. This molecule's recipe carries a
    17	 * `paddingTop`, and padding is unconditional — unlike the `gap` that every other group in
    18	 * ui-kits/ relies on, it does not collapse when the children render nothing. Without the guard
    19	 * in index.tsx, a product with neither model copy nor a style code would push 28px of empty
    20	 * space below the accordions.
    21	 */
    22	import React from 'react';
    23	import { describe, test, expect, vi, beforeEach } from 'vitest';
    24	import { render, screen } from '@testing-library/react';
    25	import { ChakraProvider } from '@chakra-ui/react';
    26	import theme from 'app/theme';
    27	
    28	const parseRichText = vi.fn();
    29	const isBlankRichText = vi.fn();
    30	vi.mock('app/utils/richText', () => ({
    31	  parseRichText: (html?: string | null) => parseRichText(html),
    32	  isBlankRichText: (html?: string | null) => isBlankRichText(html),
    33	}));
    34	
    35	import { ZimmProductMeta } from './index';
    36	
    37	const MODEL_COPY = 'Model is 178cm and wears a size 0';
    38	const STYLE_CODE = '8637DS241';
    39	
    40	beforeEach(() => {
    41	  vi.clearAllMocks();
    42	  // Input-sensitive by design — see the file docstring. MODEL_COPY is the one value these tests
    43	  // treat as real rich text; everything else, including the `<p></p>` that Business Manager
    44	  // saves for an empty field, is blank.
    45	  isBlankRichText.mockImplementation((html?: string | null) => html !== MODEL_COPY);
    46	  parseRichText.mockImplementation((html?: string | null) => (html === MODEL_COPY ? [MODEL_COPY] : []));
    47	});
    48	
    49	describe('ZimmProductMeta', () => {
    50	  test('renders both rows, model line first, when the product has model copy and a style code', () => {
    51	    render(<ZimmProductMeta modelInfo={MODEL_COPY} styleCode={STYLE_CODE} />);
    52	
    53	    const root = screen.getByTestId('product-meta');
    54	    expect(root).toBeInTheDocument();
    55	    expect(screen.getByTestId('product-model-info')).toHaveTextContent(MODEL_COPY);
    56	    expect(screen.getByTestId('product-style-code')).toBeInTheDocument();
    57	
    58	    // By position, not just presence. The recipe spaces these with one symmetrical `gap`, so
    59	    // swapping the two children in index.tsx changes nothing measurable — the block still has
    60	    // two rows 28px apart, with the style code above the model line. Only order catches it.
    61	    expect(root.children[0]).toBe(screen.getByTestId('product-model-info'));
    62	    expect(root.children[1]).toBe(screen.getByTestId('product-style-code'));
    63	  });
    64	
    65	  test('renders the model line alone when there is no style code', () => {
    66	    render(<ZimmProductMeta modelInfo={MODEL_COPY} />);
    67	
    68	    // The block must survive one absent row. A guard written with `||` instead of `&&` would
    69	    // drop the whole thing here, taking real model copy off the page — and so would a guard
    70	    // that tested `styleCode` where it should test `modelInfo`.
    71	    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
    72	    expect(screen.getByTestId('product-model-info')).toBeInTheDocument();
    73	    expect(screen.queryByTestId('product-style-code')).not.toBeInTheDocument();
    74	  });
    75	
    76	  test('renders the style code alone when there is no model copy', () => {
    77	    render(<ZimmProductMeta styleCode={STYLE_CODE} />);
    78	
    79	    // The common production shape: `c_modelFit` is unpopulated on most catalogue products, so
    80	    // this is the branch most shoppers see rather than an edge case.
    81	    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
    82	    expect(screen.queryByTestId('product-model-info')).not.toBeInTheDocument();
    83	    expect(screen.getByTestId('product-style-code')).toBeInTheDocument();
    84	  });
    85	
    86	  test.each([undefined, ''])('renders nothing at all when model copy is blank and styleCode is %s', (styleCode) => {
    87	    const { container } = render(<ZimmProductMeta modelInfo="<p></p>" styleCode={styleCode} />);
    88	
    89	    // Not "renders an empty div" — nothing. The wrapper's own `paddingTop` would otherwise be
    90	    // 28px of visible space with no content in it.
    91	    expect(container).toBeEmptyDOMElement();
    92	    expect(screen.queryByTestId('product-meta')).not.toBeInTheDocument();
    93	  });
    94	
    95	  test('resolves its recipe under a ChakraProvider — 28px of rhythm, not an inherited default', () => {
    96	    render(
    97	      <ChakraProvider theme={theme}>
    98	        <ZimmProductMeta modelInfo={MODEL_COPY} styleCode={STYLE_CODE} />
    99	      </ChakraProvider>,
   100	    );
   101	
   102	    // The only detection anywhere for this recipe losing its entry in theme/components/index.ts.
   103	    // An unregistered recipe makes `useMultiStyleConfig` return an empty object, `__css={undefined}`
   104	    // is a legal prop, and the block silently inherits — tsc, eslint and every other test in this
   105	    // file stay green. Asserting the resolved value rather than mere registration is strictly
   106	    // stronger: it also catches the recipe being registered carrying the wrong number.
   107	    //
   108	    // Measured as the declared token, not as `28px`. jsdom reports the literal CSS it was handed
   109	    // and does not resolve rem against the root font size — theme/index.test.tsx's own
   110	    // rendered-output tests record the same behaviour. index.stories.tsx's `play` measures the
   111	    // used px value in a real browser instead; the two are different measurements of the same
   112	    // declaration, not duplicates of each other.
   113	    const styles = window.getComputedStyle(screen.getByTestId('product-meta'));
   114	    expect(styles.gap).toBe('1.75rem');
   115	    expect(styles.paddingTop).toBe('1.75rem');
   116	  });
   117	});
