     1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
     2	import React from 'react';
     3	import { expect, within } from 'storybook/test';
     4	import { Box } from '@chakra-ui/react';
     5	import { ZimmProductMeta } from '.';
     6	
     7	const meta: Meta<typeof ZimmProductMeta> = {
     8	  title: 'Commerce/ZimmProductMeta',
     9	  component: ZimmProductMeta,
    10	  argTypes: {
    11	    modelInfo: { control: 'text' },
    12	    styleCode: { control: 'text' },
    13	  },
    14	  decorators: [
    15	    // The block sits in the 218px info column; at Storybook's default canvas width the 28px
    16	    // rhythm reads as arbitrary whitespace rather than as the design's spacing.
    17	    (Story: React.ComponentType) => (
    18	      <Box width="218px">
    19	        <Story />
    20	      </Box>
    21	    ),
    22	  ],
    23	};
    24	export default meta;
    25	
    26	type Story = StoryObj<typeof ZimmProductMeta>;
    27	
    28	// One story only. The two collapse branches — style code alone, and neither field — are
    29	// asserted in index.test.tsx instead: they are render-branch decisions, which is the cheaper
    30	// layer per testing.md. What that suite cannot reach, and is the whole reason this `play`
    31	// exists, is the spacing as a browser actually computes it — see the note on the assertion.
    32	export const Default: Story = {
    33	  args: {
    34	    modelInfo: 'Model is 5’9.5"/178cm, bust size 32C/10C and wears a size 0',
    35	    styleCode: '8637DS241',
    36	  },
    37	  play: async ({ canvasElement }) => {
    38	    const root = within(canvasElement).getByTestId('product-meta');
    39	
    40	    // 28px, asserted as a computed value for the same reason ZimmProductContent's
    41	    // RhythmWithDescription does it: a change to SPACE_META_ROW or to the recipe surfaces here
    42	    // rather than only in a visual review.
    43	    //
    44	    // No longer the only detection of an unregistered recipe: index.test.tsx pins the same
    45	    // declaration under a ChakraProvider and theme/index.test.tsx pins the registration itself.
    46	    // What only a real browser can prove is the *used* value — jsdom hands the declared token
    47	    // straight back ('1.75rem') and never resolves rem against the root font size, so 28px on a
    48	    // shopper's screen is asserted here and nowhere else.
    49	    //
    50	    // `rowGap`, not `gap`: the longhand names the one axis this column spaces on. Both resolve
    51	    // in a browser — Chromium returns '28px' for gap, rowGap and columnGap alike, and an element
    52	    // with no gap at all returns 'normal' — but only the longhand is browser-only, because jsdom
    53	    // does not expand the shorthand and reads rowGap back as 'normal' there.
    54	    await expect(getComputedStyle(root).rowGap).toBe('28px');
    55	
    56	    // The same const drives the space above the block, so pin both. Asserting only the gap is
    57	    // how the design's two 28px hops silently drift apart.
    58	    await expect(getComputedStyle(root).paddingTop).toBe('28px');
    59	  },
    60	};

