/** SCORER probe — NOT part of the repo. Exercises ZimmProductMeta with the REAL richText util
 *  (its own suite mocks it), plus contract assertions its own suite does not make. */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmProductMeta } from './index';

const REAL = 'Model is 5’9.5"/178cm, bust size 32C/10C and wears a size 0';

describe('SCORER: ZimmProductMeta against the real richText util', () => {
  test('P1 real rich text reaches the model atom and renders its visible text', () => {
    render(<ZimmProductMeta modelInfo={`<p>${REAL}</p>`} styleCode="8637DS241" />);
    expect(screen.getByTestId('product-model-info')).toHaveTextContent(REAL);
    expect(screen.getByTestId('product-style-code').textContent).toBe('Style Code: 8637DS241');
  });

  test('P2 exactly two element children, no wrapper leakage', () => {
    render(<ZimmProductMeta modelInfo={`<p>${REAL}</p>`} styleCode="8637DS241" />);
    const root = screen.getByTestId('product-meta');
    expect(root.children).toHaveLength(2);
    expect(root.tagName).toBe('DIV');
  });

  test('P3 real BM empty-markup shapes collapse the whole block', () => {
    for (const blank of ['<p></p>', '<br>', '   ', '<p>  </p>', '<ul><li></li></ul>']) {
      const { container, unmount } = render(<ZimmProductMeta modelInfo={blank} />);
      expect(container, `blank=${blank}`).toBeEmptyDOMElement();
      unmount();
    }
  });

  test('P4 styleCode never leaks into the model line and vice versa', () => {
    render(<ZimmProductMeta modelInfo={`<p>${REAL}</p>`} styleCode="8637DS241" />);
    expect(screen.getByTestId('product-model-info').textContent).not.toContain('8637DS241');
    expect(screen.getByTestId('product-style-code').textContent).not.toContain('178cm');
  });

  test('P5 whitespace-only styleCode still renders the block when model copy exists', () => {
    render(<ZimmProductMeta modelInfo={`<p>${REAL}</p>`} styleCode="   " />);
    expect(screen.getByTestId('product-meta')).toBeInTheDocument();
  });

  test('P6 component actually consumes its recipe (not merely registered)', () => {
    render(
      <ChakraProvider theme={theme}>
        <ZimmProductMeta modelInfo={`<p>${REAL}</p>`} styleCode="8637DS241" />
      </ChakraProvider>,
    );
    const s = window.getComputedStyle(screen.getByTestId('product-meta'));
    expect(s.display).toBe('flex');
    expect(s.flexDirection).toBe('column');
    expect(s.alignItems).toBe('flex-start');
    expect(s.gap).toBe('1.75rem');
    expect(s.paddingTop).toBe('1.75rem');
  });

  test('P7 no script execution path through model copy', () => {
    render(<ZimmProductMeta modelInfo={'<p>ok</p><script>alert(1)</script>'} styleCode="X" />);
    expect(screen.getByTestId('product-model-info').textContent).toBe('ok');
  });
});
